/* ---------- derived stats (all computed from real activity) ---------- */
const mins=from=>Math.round(d.sessions.filter(s=>s.end>=from).reduce((a,s)=>a+s.ms,0)/6e4);
const lessons=()=>Object.entries(d.curriculum).flatMap(([s,us])=>us.flatMap(u=>u.lessons.map(l=>({s,u:u.unit,l,k:[s,u.unit,l].join("|")}))));
const xp=()=>mins(0)+5*d.tasks.filter(t=>t.done).length+5*d.backlog.reduce((a,b)=>a+b.subs.filter(s=>s.done).length,0)+3*d.mistakes.filter(m=>m.rev).length+10*Object.keys(d.done).length+Math.max(0,Number(d.v6?.bonusXP)||0);
