function badges(){let L=lessons();return[["🌱","أول جلسة مذاكرة",d.sessions.length>0],["🔥","3 أيام متتالية",streak()>=3],["📘","أول درس مكتمل",Object.keys(d.done).length>0],["⏳","أنجزت درسًا متراكمًا",d.backlog.some(b=>b.subs.length&&bprog(b)===100)],["🧠","راجعت 5 أخطاء",d.mistakes.filter(m=>m.rev).length>=5],["⏱️","10 ساعات مذاكرة",mins(0)>=600]]}
