function enter(){d=R.profiles[R.active];if(!d)return welcome("dream");const tmohFromWelcome=!$("#auth").classList.contains("hide");$("#auth").classList.add("hide");$("#app").classList.remove("hide");if(tmohFromWelcome)window.TMOH_SKY?.flyIn?.();$("#userName").textContent=d.name;$("#userDream").textContent=d.demo?"ملف تجريبي":d.dream?"حلمي: "+d.dream:d.grade;$("#initial").textContent=$("#avatar").textContent=[...d.name][0];d.exams=d.exams||[];d.qbank=d.qbank||[];d.chat=d.chat||[];d.dreamGoals=d.dreamGoals||[];d.feelings=d.feelings||[];d.rewardClaims=d.rewardClaims||[];d.rewardHistory=d.rewardHistory||[];d.rewardHistory.forEach(g=>{if(g?.quizLoading){g.quizLoading=false;g.quizStatus="انقطع الاتصال أثناء تجهيز الأسئلة. اختار المستوى من جديد.";g.quiz=[];}});d.hobby=d.hobby||"";d.learningStyle=d.learningStyle||"شرح نصي";chkBeat();applyTheme();$("#nav").innerHTML=PAGES.map(p=>`<button data-page="${p[0]}">${p[1]}</button>`).join("");$$("[data-page]").forEach(b=>b.onclick=()=>go(b.dataset.page));clearInterval(tick);tick=setInterval(()=>{let c=$("#clock");if(c)c.textContent=fmt(elapsed());let t=d.timer;if(++tk%30===0)chkTasks();if(t.since){if(chkBeat()){if(page==="focus")route()}else{t.beat=Date.now();if(++hb%5===0)save()}}if(t.since&&t.goal&&!t.notified&&elapsed()>=t.goal*6e4){t.notified=true;save();msg("🎉 خلّصت هدف الجلسة! خد استراحة 5 دقايق")}let ce=d.curExam;if(ce){let l=ce.limit*6e4-(Date.now()-ce.start),e=$("#exclock");if(e)e.textContent=fmt(Math.max(0,l));if(l<=0)acts.exfin(null,true)}},1000);route();migrateImgs()}
