function plan(b){let left=b.subs.filter(x=>!x.done).length;if(!left)return"";let tot=left*(b.est||30),days=Math.ceil((new Date(b.due)-new Date(iso()))/DAY)+1,cap=d.daily||120;if(days<1)return`<p class="warn">فات موعد الانتهاء. غيّر الموعد لإعادة توزيع ${left} مهام متبقية.</p>`;let per=Math.ceil(tot/days);return`<small>الخطة: ${per} دقيقة يوميًا (${Math.ceil(left/days)} مهمة) خلال ${days} يوم.</small>`+(per>cap?`<p class="warn">الخطة أكبر من وقتك اليومي (${cap} دقيقة). أجّل الموعد ${Math.ceil(tot/cap)} أيام على الأقل أو قلّل المهام.</p>`:"")}
